class SQLQueryBuilder:

    @staticmethod
    def select(table, columns='*', where=None):
        # Handle columns parameter
        if columns == '*':
            columns_str = '*'
        elif isinstance(columns, list):
            columns_str = ', '.join(str(col) for col in columns)
        else:
            columns_str = str(columns)

        # Build SELECT and FROM parts
        query_parts = [f'SELECT {columns_str} FROM {table}']

        # Add WHERE clause if provided
        if where and isinstance(where, dict):
            conditions = []
            for key, value in where.items():
                conditions.append(f"{key}='{value}'")

            if conditions:
                query_parts.append(f"WHERE {' AND '.join(conditions)}")

        return ' '.join(query_parts)

    @staticmethod
    def insert(table, data):
        # Convert all data values to strings and escape for SQL safety
        def escape_value(value):
            # Convert to string and escape single quotes for SQL
            s_value = str(value)
            return s_value.replace("'", "''")

        columns = ', '.join(escape_value(col) for col in data.keys())
        values = ', '.join(f"'{escape_value(value)}'" for value in data.values())

        return f"INSERT INTO {table} ({columns}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        query_parts = [f'DELETE FROM {table}']
        if where and isinstance(where, dict):
            conditions = []
            for key, value in where.items():
                conditions.append(f"{key}='{value}'")
            if conditions:
                query_parts.append("WHERE " + " AND ".join(conditions))
        return ' '.join(query_parts)

    @staticmethod
    def update(table, data, where=None):
        # Validate that data is not empty - cannot update without fields to set
        if not isinstance(data, dict) or len(data) == 0:
            raise ValueError("Data cannot be empty; must contain at least one field to update")

        # Convert all data values to strings and escape for SQL safety
        def escape_value(value):
            s_value = str(value)
            return s_value.replace("'", "''")

        # Build SET clause from data
        set_parts = []
        for key, value in data.items():
            set_parts.append(f"{key}='{escape_value(value)}'")

        set_clause = ', '.join(set_parts)

        # Build query parts
        query_parts = [f"UPDATE {table} SET {set_clause}"]

        # Add WHERE clause if provided
        if where and isinstance(where, dict):
            conditions = []
            for key, value in where.items():
                conditions.append(f"{key}='{escape_value(value)}'")
            if conditions:
                query_parts.append("WHERE " + " AND ".join(conditions))

        return ' '.join(query_parts)
